use biome_js_formatter::context::JsFormatOptions;
use biome_js_formatter::format_node;
use biome_js_parser::{parse, JsParserOptions};
use biome_js_syntax::JsFileSource;

fn fmt(src: &str) -> String {
    let source_type = JsFileSource::tsx();
    let tree = parse(src, source_type, JsParserOptions::default());
    let options = JsFormatOptions::new(source_type)
        .with_indent_style(IndentStyle::Space)
        .with_line_width(LineWidth::try_from(80).unwrap());
    let doc = format_node(options, &tree.syntax()).unwrap();
    doc.print().unwrap().as_code().to_string()
}

fn main() {
    let cases = [
        // single-line: collapse empty lines (static only)
        "a.b\n\n.c;",
        // single-line: ending in method call, collapse
        "a.b\n\n.c();",
        // computed member, collapse
        "a\n\n[b].c;",
        // multiline: preserve empty line between groups
        "something.execute().then()\n\n.then().catch().anotherOne();",
        // multiline: empty line before first tail group -> expand parent
        "something\n\n.execute().then().then().catch().anotherOne();",
    ];
    for c in cases {
        println!("==== INPUT ====\n{c}\n---- OUTPUT ----\n{}\n", fmt(c));
    }
}
